import urllib.request
import urllib.error
import time
from typing import Optional

class RateLimitError(Exception):
    """Raised when the API returns a 429 Too Many Requests error."""
    pass

class ServerError(Exception):
    """Raised when the API returns a 5xx server error after retry."""
    pass

class ClientError(Exception):
    """Raised when the API returns a 4xx client error (except 429)."""
    pass

class ConnectionError(Exception):
    """Raised when a network error occurs after retry."""
    pass

class APIClient:
    def __init__(self, base_url: str, timeout: int = 10):
        self.base_url = base_url
        self.timeout = timeout

    def _make_request(self, path: str) -> str:
        url = f"{self.base_url}{path}"
        req = urllib.request.Request(url)

        # Define retry logic
        max_retries = 3
        backoff_times = [0.5, 1.0, 2.0]  # For 429

        # Specific retry for server errors and network issues (1 retry)
        server_retry_times = [1.0]

        attempt = 0

        while attempt <= max_retries:
            try:
                with urllib.request.urlopen(req, timeout=self.timeout) as response:
                    status_code = response.status
                    body = response.read().decode('utf-8')

                    if status_code == 429:
                        if attempt < len(backoff_times):
                            time.sleep(backoff_times[attempt])
                            attempt += 1
                            continue
                        else:
                            raise RateLimitError("Rate limit exceeded after retries")

                    elif 500 <= status_code < 600:
                        if attempt == 0:
                            time.sleep(1.0)
                            attempt += 1
                            continue
                        else:
                            raise ServerError(f"Server error {status_code}")

                    elif 400 <= status_code < 500:
                        if status_code == 429:
                            # Should be handled above, but just in case
                            raise RateLimitError("Rate limit exceeded")
                        raise ClientError(f"Client error {status_code}: {body}")

                    else:
                        return body

            except urllib.error.HTTPError as e:
                status_code = e.code

                if status_code == 429:
                    if attempt < len(backoff_times):
                        time.sleep(backoff_times[attempt])
                        attempt += 1
                        continue
                    else:
                        raise RateLimitError("Rate limit exceeded after retries")

                elif 500 <= status_code < 600:
                    if attempt == 0:
                        time.sleep(1.0)
                        attempt += 1
                        continue
                    else:
                        raise ServerError(f"Server error {status_code}")

                elif 400 <= status_code < 500:
                    if status_code == 429:
                        raise RateLimitError("Rate limit exceeded")
                    raise ClientError(f"Client error {status_code}: {e.read().decode('utf-8')}")

                else:
                    raise ClientError(f"Unexpected HTTP error {status_code}")

            except urllib.error.URLError as e:
                # Network error
                if attempt == 0:
                    time.sleep(1.0)
                    attempt += 1
                    continue
                else:
                    raise ConnectionError(f"Network error: {e.reason}")

            except Exception as e:
                # Catch any other unexpected errors during request
                raise ConnectionError(f"Unexpected error: {str(e)}")

        # If we exit the loop without returning or raising, something went wrong
        raise ConnectionError("Failed to connect after retries")

    def get(self, path: str) -> str:
        return self._make_request(path)
